CREATE TABLE drafts (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id      INTEGER NOT NULL,
  to_address   TEXT,
  cc_address   TEXT,
  bcc_address  TEXT,
  subject      TEXT,
  text         TEXT,
  html         TEXT,
  in_reply_to  INTEGER,                                  -- email_id being replied to
  has_attachments INTEGER NOT NULL DEFAULT 0,
  updated_at   TEXT NOT NULL DEFAULT (datetime('now')),
  created_at   TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (in_reply_to) REFERENCES emails(id) ON DELETE SET NULL
);
CREATE TABLE signatures (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id     INTEGER NOT NULL,
  name        TEXT NOT NULL DEFAULT 'Default',
  html        TEXT,
  is_default  INTEGER NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE user_settings (
  user_id             INTEGER PRIMARY KEY,
  theme               TEXT NOT NULL DEFAULT 'light',     -- light | dark
  density             TEXT NOT NULL DEFAULT 'comfortable', -- comfortable | compact
  language            TEXT NOT NULL DEFAULT 'en',
  signature_html      TEXT,
  auto_save_drafts    INTEGER NOT NULL DEFAULT 1,
  show_snippets       INTEGER NOT NULL DEFAULT 1,
  items_per_page      INTEGER NOT NULL DEFAULT 50,
  reply_to_address    TEXT,
  forward_to_address  TEXT,
  notify_on_new_email INTEGER NOT NULL DEFAULT 0,
  created_at          TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at          TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
INSERT INTO "user_settings" ("user_id","theme","density","language","signature_html","auto_save_drafts","show_snippets","items_per_page","reply_to_address","forward_to_address","notify_on_new_email","created_at","updated_at") VALUES(1,'light','comfortable','en',NULL,1,1,50,NULL,NULL,0,'2026-09-01 19:09:22','2026-09-01 19:09:22');
