CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);
CREATE INDEX idx_folders_user ON folders(user_id);
CREATE INDEX idx_emails_user_folder ON emails(user_id, folder_id);
CREATE INDEX idx_emails_user_starred ON emails(user_id, is_starred);
CREATE INDEX idx_emails_thread ON emails(thread_id);
CREATE INDEX idx_emails_received ON emails(user_id, received_at DESC);
CREATE INDEX idx_emails_search ON emails(user_id, subject, from_address, to_address, text);
CREATE INDEX idx_labels_user ON labels(user_id);
CREATE INDEX idx_email_labels_email ON email_labels(email_id);
CREATE INDEX idx_email_labels_label ON email_labels(label_id);
CREATE INDEX idx_attachments_email ON attachments(email_id);
CREATE INDEX idx_attachments_user ON attachments(user_id);
CREATE INDEX idx_drafts_user ON drafts(user_id);
CREATE INDEX idx_signatures_user ON signatures(user_id);
CREATE INDEX idx_aliases_email ON aliases(alias_email);
CREATE INDEX idx_audit_user ON audit_logs(user_id, created_at DESC);
CREATE INDEX idx_audit_action ON audit_logs(action);
CREATE INDEX idx_contacts_user ON contacts(user_id);
CREATE INDEX idx_contacts_email ON contacts(user_id, email);
CREATE INDEX idx_calendar_user ON calendar_events(user_id, start_time);
CREATE INDEX idx_chat_conv_user ON chat_conversations(user_id);
CREATE INDEX idx_chat_msg_conv ON chat_messages(conversation_id, created_at);
CREATE INDEX idx_files_user ON files(user_id);
CREATE INDEX idx_templates_user ON email_templates(user_id);
CREATE INDEX idx_rules_user ON email_rules(user_id);
CREATE INDEX idx_receipts_email ON read_receipts(email_id);
CREATE INDEX idx_seclog_user ON security_log(user_id, created_at DESC);
